import{_ as o,o as e,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const q=JSON.parse('{"title":"HJ95 人民币转换","description":"较难 通过率：27.03% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 考试题目和要点： 1、中文大写金额数字前应标明“人民币”字样。中文大写金额数字应用壹、贰、叁、肆、伍、陆、柒、捌、玖、拾、佰、仟、万、亿、元、角、分、零、整等字样填写。 2、中文大写金额数字到“元。","frontmatter":{"title":"HJ95 人民币转换","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"较难 通过率：27.03% 时间限制：1秒 空间限制：32M 知识点 字符串 描述 考试题目和要点： 1、中文大写金额数字前应标明“人民币”字样。中文大写金额数字应用壹、贰、叁、肆、伍、陆、柒、捌、玖、拾、佰、仟、万、亿、元、角、分、零、整等字样填写。 2、中文大写金额数字到“元。","sidebarWeight":94,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为较难题/HJ95 人民币转换.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ95 人民币转换.md","filePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ95 人民币转换.md"}'),a={name:"posts/前端面试与实战/03-算法训练/华为较难题/HJ95 人民币转换.md"};function n(s,t,l,d,c,u){return e(),r("div",null,[...t[0]||(t[0]=[i('<div><h1 id="hj95-人民币转换" tabindex="-1">HJ95 人民币转换 <a class="header-anchor" href="#hj95-人民币转换" aria-label="Permalink to &quot;HJ95 人民币转换&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ95 人民币转换”的核心思路，并能把它用于实际开发或面试表达。 较难 通过率：27.03% 时间限制：1秒 空间限制：32M 知识点==字符串== <strong>描述</strong> 考试题目和要点： 1、中文大写金额数字前应标明“人民币”字样。中文大写金额数字应用壹、贰、叁、肆、伍、陆、柒、捌、玖、拾、佰、仟、万、亿、元、角、分、零、整等字样填写。 2、中文大写金额数字到“元”为止的，在“元”之后，应写“整字，如532.00应写成“人民币伍佰叁拾贰元整”。在”角“和”分“后面不写”整字。 3、阿拉伯数字中间有“0”时，中文大写要写“零”字，阿拉伯数字中间连续有几个“0”时，中文大写金额中间只写一个“零”字，如6007.14，应写成“人民币陆仟零柒元壹角肆分“。 4、10应写作“拾”，100应写作“壹佰”。例如，1010.00应写作“人民币壹仟零拾元整”，110.00应写作“人民币壹佰拾元整” 5、十万以上的数字接千不用加“零”，例如，30105000.00应写作“人民币叁仟零拾万伍仟元整” <strong>输入描述：</strong> 输入一个double数 <strong>输出描述：</strong> 输出人民币格式 <strong>示例1</strong> 输入： 151121.15 ==复制== 输出： 人民币拾伍万壹仟壹佰贰拾壹元壹角伍分 ==复制== <strong>示例2</strong> 输入： 1010.00 ==复制== 输出： 人民币壹仟零拾元整 ==复制==</p></blockquote><p>当然！我们的目标是把数字转换成中文的钱的形式。比如，13.64元要变成“人民币拾叁元陆角肆分”。我们分几步来做这个转换：</p><ol><li>把整数和小数部分分开。</li><li>把整数部分的每一位数字转成中文。</li><li>把小数部分的每一位数字转成中文。</li><li>在正确的位置加上“拾”、“佰”、“仟”等中文单位。</li><li>如果十位上的数字是1，我们就直接说“拾”而不是“壹拾”。</li><li>如果有连续的零，我们只说一次“零”。</li><li>最后把所有的部分合起来，就得到了完整的中文钱的形式。</li></ol><p>好，现在我们开始给代码加注释，就像在给五岁的孩子讲故事一样。</p><h1 id="这是将数字转换成中文金额表示的函数" tabindex="-1">这是将数字转换成中文金额表示的函数 <a class="header-anchor" href="#这是将数字转换成中文金额表示的函数" aria-label="Permalink to &quot;这是将数字转换成中文金额表示的函数&quot;">​</a></h1><p>def convert_to_chinese_currency(num_str):</p><h1 id="这些是中文数字-从-零-到-玖" tabindex="-1">这些是中文数字，从&quot;零&quot;到&quot;玖&quot; <a class="header-anchor" href="#这些是中文数字-从-零-到-玖" aria-label="Permalink to &quot;这些是中文数字，从&quot;零&quot;到&quot;玖&quot;&quot;">​</a></h1><p>digits = &quot;零壹贰叁肆伍陆柒捌玖&quot;</p><h1 id="这些是单位-从个位开始到千位" tabindex="-1">这些是单位，从个位开始到千位 <a class="header-anchor" href="#这些是单位-从个位开始到千位" aria-label="Permalink to &quot;这些是单位，从个位开始到千位&quot;">​</a></h1><p>units = [&quot;&quot;, &quot;拾&quot;, &quot;佰&quot;, &quot;仟&quot;]</p><h1 id="这些是更大的单位-从万开始" tabindex="-1">这些是更大的单位，从万开始 <a class="header-anchor" href="#这些是更大的单位-从万开始" aria-label="Permalink to &quot;这些是更大的单位，从万开始&quot;">​</a></h1><p>big_units = [&quot;&quot;, &quot;万&quot;, &quot;亿&quot;, &quot;兆&quot;]</p><h1 id="这个函数是用来转换整数部分的" tabindex="-1">这个函数是用来转换整数部分的 <a class="header-anchor" href="#这个函数是用来转换整数部分的" aria-label="Permalink to &quot;这个函数是用来转换整数部分的&quot;">​</a></h1><p>def convert_integer_part(integer_str): result = &quot;&quot; # 这是我们将要建立的字符串 str_len = len(integer_str) # 计算数字的长度</p><h1 id="将整数部分分成每四位一组" tabindex="-1">将整数部分分成每四位一组 <a class="header-anchor" href="#将整数部分分成每四位一组" aria-label="Permalink to &quot;将整数部分分成每四位一组&quot;">​</a></h1><p>groups = [integer_str[max(0, i - 4): i] for i in range(str_len, 0, -4)][::-1]</p><h1 id="对每组数字进行处理" tabindex="-1">对每组数字进行处理 <a class="header-anchor" href="#对每组数字进行处理" aria-label="Permalink to &quot;对每组数字进行处理&quot;">​</a></h1><p>for idx, grp in enumerate(groups): grp_str = &quot;&quot; # 这是每组的字符串 zero_flag = False # 这个标记用来记住我们是否需要加&quot;零&quot; for i, digit in enumerate(grp[::-1]): # 从右向左查看每一位数字 digit = int(digit) # 将字符转换成数字 if digit == 0: # 如果数字是0 zero_flag = True else: if zero_flag: # 如果之前有0，我们需要加一个&quot;零&quot; grp_str = &quot;零&quot; + grp_str zero_flag = False</p><h1 id="特别处理-拾-的情况" tabindex="-1">特别处理&quot;拾&quot;的情况 <a class="header-anchor" href="#特别处理-拾-的情况" aria-label="Permalink to &quot;特别处理&quot;拾&quot;的情况&quot;">​</a></h1><p>if i == 1 and digit == 1 and len(grp) &gt; 1: grp_str = units[i] + grp_str else: # 正常情况下，加上数字和单位 grp_str = digits[digit] + units[i] + grp_str if int(grp) != 0: # 如果这组数字不全是0 grp_str += big_units[len(groups) - idx - 1] # 加上大单位，比如&quot;万&quot;、&quot;亿&quot; if zero_flag and idx != len(groups) - 1: # 如果需要，前面加上&quot;零&quot; grp_str = &quot;零&quot; + grp_str result += grp_str # 将这组的字符串加到结果中 return result + &quot;元&quot; # 最后加上&quot;元&quot;</p><h1 id="这个函数是用来转换小数部分的" tabindex="-1">这个函数是用来转换小数部分的 <a class="header-anchor" href="#这个函数是用来转换小数部分的" aria-label="Permalink to &quot;这个函数是用来转换小数部分的&quot;">​</a></h1><p>def convert_decimal_part(decimal_str): part = &quot;&quot; # 这是我们将要建立的字符串 if decimal_str[0] != &quot;0&quot;: # 如果角位不是0 part += digits[int(decimal_str[0])] + &quot;角&quot; # 加上角的表示 if decimal_str[1] != &quot;0&quot;: # 如果分位不是0 part += digits[int(decimal_str[1])] + &quot;分&quot; # 加上分的表示 return part if part else &quot;整&quot; # 如果没有小数，就加上&quot;整&quot;</p><h1 id="确保输入的数字有两位小数" tabindex="-1">确保输入的数字有两位小数 <a class="header-anchor" href="#确保输入的数字有两位小数" aria-label="Permalink to &quot;确保输入的数字有两位小数&quot;">​</a></h1><p>num_str = format(float(num_str), &quot;.2f&quot;)</p><h1 id="分割整数部分和小数部分" tabindex="-1">分割整数部分和小数部分 <a class="header-anchor" href="#分割整数部分和小数部分" aria-label="Permalink to &quot;分割整数部分和小数部分&quot;">​</a></h1><p>integer_part, decimal_part = num_str.split(&quot;.&quot;)</p><h1 id="开始建立整个字符串" tabindex="-1">开始建立整个字符串 <a class="header-anchor" href="#开始建立整个字符串" aria-label="Permalink to &quot;开始建立整个字符串&quot;">​</a></h1><p>chinese_currency = &quot;人民币&quot; # 先加上&quot;人民币&quot; if integer_part != &quot;0&quot;: # 如果整数部分不是0 chinese_currency += convert_integer_part(integer_part) # 加上整数部分的中文表示 chinese_currency += convert_decimal_part(decimal_part) # 加上小数部分的中文表示 return chinese_currency # 返回最终的字符串</p><h1 id="读取一个数字-然后把它转换成中文金额表示" tabindex="-1">读取一个数字，然后把它转换成中文金额表示 <a class="header-anchor" href="#读取一个数字-然后把它转换成中文金额表示" aria-label="Permalink to &quot;读取一个数字，然后把它转换成中文金额表示&quot;">​</a></h1><p>print(convert_to_chinese_currency(input())) # 期望输出：人民币拾伍万壹仟壹佰贰拾壹元壹角伍分</p><p>这个故事告诉我们怎么把数字变成中文的钱的样子。我们按照中文的习惯，一个一个数字地说出来，然后加上合适的单位。如果有很多零，我们只说一次零。还有，如果十位是1，我们就直接说拾。我们小心地说这些数字和单位，直到我们讲出完整的故事。</p><p><strong>if</strong> <strong>not</strong> <strong>integer_str</strong>**😗* <code>if not integer_str:</code> 这行代码会在 <code>integer_str</code> 是一个空字符串时成立。在这个特定的转换函数中，空字符串会出现在我们去除了整数部分开头所有的 &#39;0&#39; 之后，如果原始的整数部分仅由 &#39;0&#39; 组成。</p><p>例如，如果我们开始有一个数字 <code>0.85</code>，那么在执行 <code>integer_part.lstrip(&#39;0&#39;)</code> 后，整数部分（<code>integer_part</code>）会从 <code>&#39;0&#39;</code> 变成一个空字符串 <code>&#39;&#39;</code>，因为我们移除了前面的零。此时，<code>if not integer_str:</code> 这个条件就会成立，函数会返回 <code>&#39;零元&#39;</code>。这样做是为了确保在只有小数部分，没有整数部分时（即，整数部分为0时），我们能够正确地输出中文金额表示。</p><p><strong>字符串转数字时的<strong><strong>0</strong></strong>的处理</strong></p><ol><li><strong>转换为整数 (<code>int</code>)：</strong></li></ol><ul><li>如果字符串不包含小数点，即被视为整数，那么将所有前置零去掉。转换结果仅反映非零数字部分。</li><li>例如：<code>&#39;000123&#39;</code> 转换后为整数 <code>123</code>。</li></ul><ol start="2"><li><strong>转换为浮点数 (<code>float</code>)：</strong></li></ol><ul><li>如果字符串包含小数点，即被视为浮点数：</li><li><strong>小数部分：</strong> 不做任何处理，保留原样，包括任何零。这是因为小数部分的零可能影响数值的精度和表示。</li><li>例如：<code>&#39;0.0500&#39;</code> 保留为浮点数 <code>0.0500</code>。</li><li><strong>整数部分：</strong></li><li>如果整数部分的值等于0（即小数点前全是零或仅一个零），则保留一个零。这符合浮点数表示法，确保了数值小于1时的正确表示。</li><li>例如：<code>&#39;0.123&#39;</code> 转换后为浮点数 <code>0.123</code>。</li><li>如果整数部分的值不等于0，则去掉所有前置零，仅保留数值有效部分。</li><li>例如：<code>&#39;000123.456&#39;</code> 转换后为浮点数 <code>123.456</code>。</li></ul><p>通过这样的规则，我们可以清楚地区分整数和浮点数的转换处理，同时准确地反映原始数据的意图，无论是在数值的大小还是在精度上。这套规则旨在确保数值转换的过程中，无论是整数还是浮点数，前置零的处理都是适当和准确的。</p><p><strong>groups</strong> <strong>= [<strong><strong>integer_str</strong></strong>[<strong><strong>max</strong></strong>(<strong><strong>0</strong></strong>,</strong> <strong>i</strong> <strong>-</strong> <strong>4</strong>**)😗* <strong>i</strong>**]** <strong>for</strong> <strong>i</strong> <strong>in</strong> <strong>range</strong>**(<strong><strong>str_len</strong></strong>,** <strong>0</strong>**, -<strong><strong>4</strong></strong>)][::-<strong><strong>1</strong></strong>]** 这行代码的目的是将一个整数字符串分割成每四位一组的小段，以便按照中文的计数习惯（个、十、百、千、万、亿）来处理。下面是这行代码的详细介绍：</p><ol><li><code>for i in range(str_len, 0, -4)</code></li></ol><ul><li>这部分是一个 <code>for</code> 循环，使用 <code>range</code> 函数生成一个序列。</li><li><code>str_len</code> 是整数部分字符串的长度。</li><li><code>range</code> 函数的起始值是 <code>str_len</code>（整数部分的长度），结束值是 <code>0</code>，步长是 <code>-4</code>。</li><li>这意味着 <code>i</code> 会从字符串的末尾开始，每次向前移动4个字符的位置，直到到达字符串的开始。</li></ul><ol start="2"><li><code>integer_str[max(0, i - 4) : i]</code></li></ol><ul><li>对于每一个 <code>i</code>，这个表达式都会从整数字符串中截取一个子字符串。</li><li><code>i - 4</code> 计算的是子字符串的起始位置（从右向左数），<code>i</code> 是结束位置。</li><li>使用 <code>max(0, i - 4)</code> 确保起始位置不会小于0，这是因为当处理字符串的最左边几位时，<code>i - 4</code> 可能会是一个负数。</li><li>所以，这个表达式会从整数字符串中截取从第 <code>i - 4</code> 位到第 <code>i</code> 位（不包含第 <code>i</code> 位本身）的子字符串。</li></ul><ol start="3"><li><code>[...]</code></li></ol><ul><li>这个方括号表示列表推导式，用于创建一个新的列表，列表中的每个元素都是通过上面描述的过程计算得到的子字符串。</li></ul><ol start="4"><li><code>[...][::-1]</code></li></ol><ul><li>最后，<code>[::-1]</code> 是一个列表的切片操作，用于将列表反转。</li><li>这是因为我们从字符串的末尾开始分割，最先生成的子字符串实际上对应整数的最低位的四位数字。</li><li>为了使得子字符串列表的顺序与数字的自然顺序（即从左到右）一致，我们需要将列表反转。</li></ul><p>综上所述，这行代码将整数字符串按照每四位数字一组的方式分割成多个子字符串，并且这些子字符串的顺序与原始整数中数字的顺序一致。这样的分割方式符合中文数字的读写习惯，便于后续按中文的方式将数字转换为文字描述。</p></div>',1)])])}const p=o(a,[["render",n]]);export{q as __pageData,p as default};
